namespace ghidra.graph.viewer.layout;



/**
 * Class for reporting the min/max columns in a row or the min/max rows in a column
 */
public class GridRange {
	public int min;
	public int max;

	public GridRange() : this(int.MaxValue, int.MinValue)
    {
	}

	public GridRange(int min, int max) {
		this.min = min;
		this.max = max;
	}

	public void add(int value) {
		min = Math.min(value, min);
		max = Math.max(value, max);
	}

	/* @Override */
	public string toString() {
		return "[" + min + " -> " + max + "]";
	}

	public bool isEmpty() {
		return min > max;
	}

	public bool contains(int value) {
		return value >= min && value <= max;
	}

	/* @Override */
	public int hashCode() {
		return Objects.hash(max, min);
	}

	/* @Override */
	public bool equals(object obj) {
		if (this == obj)
			return true;
		if (obj == null)
			return false;
		if (getClass() != obj.GetType())
			return false;
		GridRange other = (GridRange) obj;
		return max == other.max && min == other.min;
	}

	public int width() {
		if (isEmpty()) {
			return 0;
		}
		return max - min + 1;
	}

}
